target.css:
:root {
  --card: #fffdf7;
  --ink: #24352d;
  --line: #d8e4d8;
  --mint: #dff2df;
  --green: #286344;
}

.donation-card {
  width: 460px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  color: var(--ink);
}

.donation-card header,
.donation-card footer,
.title-row,
.details {
  display: flex;
  align-items: center;
}

.donation-card header {
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}

.title-row {
  gap: 10px;
}

.crate {
  font-size: 27px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--green);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.open-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--green);
  font-size: 11px;
  font-weight: 700;
}

.details {
  gap: 24px;
  padding: 14px 16px;
  font-size: 14px;
  line-height: 1.45;
}

.details p {
  margin: 0;
}

.note {
  padding-left: 24px;
  border-left: 1px solid var(--line);
}

.donation-card footer {
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--mint);
  color: var(--green);
  font-size: 12px;
  font-weight: 600;
}

button {
  padding: 6px 10px;
  border: 1px solid var(--green);
  border-radius: 6px;
  background: var(--card);
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
}
